// Parser for AI output with embedded JSON blocks and interview scheduling

const rawOutput = items[0].json.output;

let analysisData = {};
let rejectionLetter = "";
let interviewDate = "";
let interviewStart = "";
let interviewEnd = "";

try {
  /* --------------------------------------------------
     1. Extract ANALYSIS_DATA JSON (first json block)
  -------------------------------------------------- */
  const jsonBlocks = rawOutput.match(/```json[\s\S]*?```/g);

  if (jsonBlocks && jsonBlocks.length > 0) {
    const analysisJson = jsonBlocks[0]
      .replace(/```json|```/g, "")
      .trim();
    analysisData = JSON.parse(analysisJson);
  }

  /* --------------------------------------------------
     2. Extract REJECTION / INTERVIEW text
  -------------------------------------------------- */
  const rejectionSplit = rawOutput.split("SECTION 2:");
  rejectionLetter = rejectionSplit.length > 1
    ? rejectionSplit[1].trim()
    : "";

  /* --------------------------------------------------
     3. Extract interview times from JSON (if present)
  -------------------------------------------------- */
  if (jsonBlocks && jsonBlocks.length > 1) {
    const interviewJson = jsonBlocks[1]
      .replace(/```json|```/g, "")
      .trim();

    const interviewData = JSON.parse(interviewJson);

    if (interviewData.interview_start) {
      const start = new Date(interviewData.interview_start);
      interviewDate = start.toISOString().split("T")[0];
      interviewStart = start.toISOString().split("T")[1].substring(0, 5);
    }

    if (interviewData.interview_end) {
      const end = new Date(interviewData.interview_end);
      interviewEnd = end.toISOString().split("T")[1].substring(0, 5);
    }
  }

  /* --------------------------------------------------
     4. Fallback: extract Start / End Time from text
  -------------------------------------------------- */
  if (!interviewStart) {
    const startMatch = rawOutput.match(/\*\*Start Time\*\*:\s*([0-9T:\-]+)/i);
    if (startMatch) {
      const start = new Date(startMatch[1]);
      interviewDate = start.toISOString().split("T")[0];
      interviewStart = start.toISOString().split("T")[1].substring(0, 5);
    }
  }

  if (!interviewEnd) {
    const endMatch = rawOutput.match(/\*\*End Time\*\*:\s*([0-9T:\-]+)/i);
    if (endMatch) {
      const end = new Date(endMatch[1]);
      interviewEnd = end.toISOString().split("T")[1].substring(0, 5);
    }
  }

} catch (error) {
  analysisData = { error: "Failed to parse AI output", raw: rawOutput };
}

/* --------------------------------------------------
   5. Final normalized output
-------------------------------------------------- */
return {
  candidate_name: analysisData.candidate_name || "Unknown",
  match_score: analysisData.match_score || 0,
  pros: Array.isArray(analysisData.pros) ? analysisData.pros.join(", ") : "",
  cons: Array.isArray(analysisData.cons) ? analysisData.cons.join(", ") : "",
  matched_role: analysisData.matched_role || "",
  rejection_letter: rejectionLetter,
  interview_date: interviewDate || "Unknown",
  interview_start_time: interviewStart || "Unknown",
  interview_end_time: interviewEnd || "Unknown",
  is_shortlisted: analysisData.match_score >= 70
};
